import {createSession,act,getGroup,currentRep,phase,elapsed,recoveryRemaining,exportCsv,exportDetailCsv,formatTime,shortTime,parseWorkout,getPlan,getStep,workoutSummary,workoutLines,athletePlan,splitCapacity,SAMPLE_WORKOUT,parsePractice,createSessionFromPractice,PRACTICE_EXAMPLE,goalFor,goalText,goalString,plannedDistances,buildSheetPayload} from './engine.mjs';

const KEY='terrier-timing-v2', ARCHIVE='terrier-timing-archives-v2';
const $=s=>document.querySelector(s), e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={clock:'<circle cx="12" cy="13" r="8"/><path d="M12 9v4l3 2M9 2h6m-3 0v3m6 1 2 2"/>',play:'<path d="m9 5 11 7-11 7z"/>',flag:'<path d="M5 21V4m0 0c5-4 9 4 14 0v10c-5 4-9-4-14 0"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',chart:'<path d="M4 19V5m0 14h17M9 15v-5m5 5V6m5 9v-3"/>',settings:'<path d="M4 7h8m4 0h4M4 17h4m4 0h8"/><circle cx="14" cy="7" r="2"/><circle cx="10" cy="17" r="2"/>',check:'<path d="m5 12 4 4L19 6"/>',save:'<path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h12l4 4v12a2 2 0 0 1-2 2Z"/><path d="M7 21v-8h10v8M7 3v5h9"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',undo:'<path d="M3 10h12a6 6 0 0 1 0 12M3 10l6-6M3 10l6 6" transform="translate(0 -2)"/>',more:'<circle cx="12" cy="5" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="12" cy="19" r="1"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6L16 3Zm-2 2 5 5"/>',leaf:'<path d="M20 4c-10-2-18 4-14 12s16 3 14-12ZM5 20 16 9"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',folder:'<path d="M3 7V4h6l2 3h10v13H3Z"/>',reset:'<path d="M3 10a9 9 0 1 1 2 9M3 4v6h6"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="2"/>',grip:'<circle cx="9" cy="6" r="1.4"/><circle cx="15" cy="6" r="1.4"/><circle cx="9" cy="12" r="1.4"/><circle cx="15" cy="12" r="1.4"/><circle cx="9" cy="18" r="1.4"/><circle cx="15" cy="18" r="1.4"/>',trash:'<path d="M4 7h16M10 11v6m4-6v6M6 7l1 13h10l1-13M9 7V4h6v3"/>'};
const icon=(name,size=19)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.clock}</svg>`;
const total=g=>getPlan(g).length;
const hasData=r=>r.closed||Object.keys(r.starts).length||Object.keys(r.finishes).length||r.skipped.some(id=>!(r.modSkipped||[]).includes(id))||r.unassigned.length;
const clone=x=>JSON.parse(JSON.stringify(x));
let session, storageOk=true;
try {const s=JSON.parse(localStorage.getItem(KEY)||localStorage.getItem('stride-trackside-v1'));session=s?.groups?.length?s:createSession();getGroup(session);}catch{session=createSession();}
let view='live',history=[],toastTimer, lastPhase='',audioContext, alerted=new Set();
let soundOn=false;
const archiveRead=()=>{try{return JSON.parse(localStorage.getItem(ARCHIVE)||localStorage.getItem('stride-trackside-archives-v1'))||[];}catch{return [];}};
function persist(){try{localStorage.setItem(KEY,JSON.stringify(session));storageOk=true;}catch{storageOk=false;toast('Browser storage is unavailable. Export results to keep them.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function dispatch(action,notice){try{const next=act(session,{groupId:session.activeGroupId,...action});if(action.type!=='SELECT_GROUP'&&action.type!=='SET_PREF'){history.push(clone(session));if(history.length>40)history.shift();}session=next;persist();render();autoSend(action);if(notice)toast(notice);return true;}catch(err){toast(err.message);return false;}}
function undo(){if(!history.length)return;session=history.pop();persist();render();toast('Last action undone.');}
function current(){return getGroup(session);}
const initials=name=>name.trim().split(/\s+/).map(n=>n[0]).slice(0,2).join('');
const dateLabel=()=>new Date(session.createdAt).toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'});
const restText=s=>s>=60?`${Math.floor(s/60)} min${s%60?' '+(s%60)+' sec':''}`:`${s} sec`;
const repLabel=(g,i=g.repIndex)=>{const step=getStep(g,i);return g.mode==='free'?`Rep ${i+1}`:step?`Block ${step.blockIndex+1} · Rep ${step.repInBlock}/${step.repsInBlock} · ${i+1} of ${total(g)}`:'Complete';};
const workoutLabel=g=>workoutSummary(g);
function badgeText(g){const p=phase(g);return p==='complete'?'Complete':p==='recovery'?'Resting':p==='ready-next'?'Next rep':p==='running'?'Running':'Ready';}

const clockMs=(ms,up)=>{const s=Math.max(0,up?Math.floor(ms/1000):Math.ceil(ms/1000));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;};
const isLive=(r,id)=>r.starts[id]!=null&&!r.finishes[id]&&!r.skipped.includes(id);
function tabStatus(g,now=Date.now()){const p=phase(g,now);if(p==='complete')return 'Complete';if(g.recovery){const rem=recoveryRemaining(g,now);return rem>0?`Rest ${clockMs(rem,false)}`:'Rest over';}if(p==='running'){const r=currentRep(g),starts=Object.values(r.starts);if(starts.length&&g.athletes.some(a=>isLive(r,a.id)))return `Running ${clockMs(now-Math.min(...starts),true)}`;}return badgeText(g);}
const tabAttention=(g,now=Date.now())=>!!g.recovery&&!g.completed&&recoveryRemaining(g,now)<=0;
function cellMeta(g,r,a){const plan=athletePlan(g,a,r.index),list=(r.splits||{})[a.id]||[],bits=[];if(g.mode==='planned'&&plan.modified&&!plan.skip)bits.push(`<span class="cell-dist">${fmtDist(plan.distance)}</span>`);if(list.length)bits.push(`<span class="cell-splits">${list.map(sp=>shortTime(sp.ms)).join(' · ')}</span>`);return bits.join('');}

const PACK_COLORS=['#1644c8','#e32636','#0b8f6a','#c27a00','#7b3fc4','#00859a','#b8307a','#5f6b7d'];
const packColor=(g,p)=>PACK_COLORS[Math.max(0,(g.packs||[]).findIndex(x=>x.id===p.id))%PACK_COLORS.length];
const sortPref=()=>session.prefs?.finishedToBottom!==false;
const fmtDist=d=>`${+Number(d).toFixed(3)}m`;
const parseDist=v=>{const t=String(v??'').trim().replace(/m$/i,'');if(!t)return null;const n=Number(t);if(!(n>0)||n>100000)throw new Error('Distances are in meters, like 1200.');return n;};
function workoutStrip(g){if(g.mode==='free')return '';const lines=workoutLines(g),step=getStep(g),cur=step?.blockIndex??-1;if(!lines)return `<section class="workout-strip" aria-label="Workout"><span class="wl current">${e(workoutSummary(g))}</span></section>`;return `<section class="workout-strip" aria-label="Workout">${lines.map(l=>{const state=g.completed||cur>l.blocks.at(-1)?'done':cur>=l.blocks[0]?'current':'';return `<span class="wl ${state}">${e(l.text)}${l.restText?`<i>${e(l.restText)}</i>`:''}</span>`;}).join('')}</section>`;}
const timerContext=(g,s)=>{if(g.mode==='free')return `Rep ${g.repIndex+1}`;if(!s)return 'Complete';const rest=s.restAfterSeconds&&g.repIndex<total(g)-1?` · ${restText(s.restAfterSeconds)} rest`:'';return `Rep ${s.repInBlock}/${s.repsInBlock} · ${g.repIndex+1} of ${total(g)}${rest}`;};
function upNext(g){if(g.completed)return '<span class="upnext-label">All results saved</span>';if(g.mode==='free')return '<span class="upnext-label">Free timing</span>';const rest=getPlan(g).slice(g.repIndex+1);if(!rest.length)return '<span class="upnext-label">Last rep</span>';return `<span class="upnext-label">Next</span><span class="upnext-chips" data-upnext>${rest.map((s,i)=>`<span class="uchip ${i&&rest[i-1].blockIndex!==s.blockIndex?'newblock':''}">${e(s.label)}</span>`).join('')}</span><span class="upnext-more" data-upnext-more></span>`;}
function fitUpcoming(){const box=document.querySelector('[data-upnext]'),more=document.querySelector('[data-upnext-more]');if(!box||!more)return;const chips=[...box.children];if(!chips.length)return;const top=chips[0].offsetTop;let shown=chips.length;for(let i=0;i<chips.length;i++)if(chips[i].offsetTop>top){shown=i;break;}more.textContent=shown<chips.length?`+${chips.length-shown}`:'';}

function btn(text,action,options={}){return `<button class="btn ${options.class||''}" data-action="${action}" ${options.attrs||''} ${options.disabled?'disabled':''}>${options.icon?icon(options.icon):''}${text}</button>`;}

function shell(content){return `<div class="shell"><aside class="sidebar"><nav class="nav" aria-label="Main navigation">${[['live','clock','Timer'],['results','chart','Results'],['setup','settings','Workout']].map(([id,ic,title])=>`<button class="${view===id?'active':''}" data-view="${id}" ${view===id?'aria-current="page"':''}>${icon(ic,21)}<span>${title}</span></button>`).join('')}</nav></aside><main class="main"><header class="topbar"><div class="mobile-brand"><img class="brand-logo" src="./logo.png" alt="St. Francis Prep Terrier"><span>Terrier Timing<small>ST. FRANCIS PREP</small></span></div><span class="saved">${icon(storageOk?'check':'info',15)} ${storageOk?'Saved locally':'Export to save'}</span></header>${content}<footer class="session-footer">Phone layout prototype · Sample roster · Saved in this browser</footer></main></div>`;}
function intro(title,subtitle,actions='',classes=''){return `<section class="intro ${classes}"><div><h1>${e(title)}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div><div class="intro-actions">${actions}</div></section>`;}
function groupTabs(){return `<div class="group-tabs" aria-label="Workout groups">${session.groups.map(g=>`<button class="group-tab ${g.id===session.activeGroupId?'active':''} ${g.color} ${tabAttention(g)?'attention':''}" data-group-tab="${e(g.id)}" data-action="select-group" data-group="${e(g.id)}" aria-pressed="${g.id===session.activeGroupId}"><span><strong>${e(g.name)}</strong><small><span class="tab-status" data-group-phase="${e(g.id)}">${tabStatus(g)}</span> · ${g.athletes.length}</small></span></button>`).join('')}<button class="add-group" data-action="add-group" aria-label="Add a group">${icon('plus')}</button></div>`;}
function timerCard(g){const p=phase(g),r=currentRep(g),s=getStep(g),next=getStep(g,g.repIndex+1),started=Object.keys(r.starts).length,done=Object.keys(r.finishes).length+r.skipped.length,running=g.athletes.some(a=>r.starts[a.id]!=null&&!r.finishes[a.id]&&!r.skipped.includes(a.id)),canReset=p==='running'||p==='recovery'||p==='ready-next';let actions='';
  if(p==='complete')actions=btn('Results','view-results',{icon:'chart',class:'primary'})+btn('Extra rep','add-rep',{icon:'plus'});
  else if(p==='ready')actions=btn('Start all','start-all',{icon:'play',class:'primary'})+btn('Start rest','start-recovery',{icon:'clock'});
  else if(g.recovery)actions=(running?btn('Capture finish','quick-finish',{icon:'flag',class:'capture'}):'')+btn('Next rep','next-rep',{icon:'play',class:running?'':'primary'})+btn('+30s','add-rest',{attrs:'data-seconds="30"',class:'rest-add'});
  else if(done===g.athletes.length)actions=btn('Start rest','start-recovery',{icon:'clock',class:'primary'})+btn('Next rep','next-rep',{icon:'play'});
  else actions=btn('Capture finish','quick-finish',{icon:'flag',class:'capture',disabled:!started})+btn('Start rest','start-recovery',{icon:'clock'});
  const stepTitle=p==='complete'?'Workout complete':g.recovery?'Recovery':s?.label||'Free timing';
  return `<section class="timing-card" aria-label="Group stopwatch"><div class="timer-top"><span class="timer-step-title">${e(stepTitle)}</span><span class="timer-top-right">${canReset?`<button class="timer-reset" data-action="reset-menu" aria-label="Stop or reset the clock">${icon('reset',14)}Reset</button>`:''}<span class="phase-pill"><span data-phase-label>${p==='running'?'RUNNING':p==='recovery'?'RECOVERY':p==='complete'?'SAVED':'READY'}</span></span></span></div><div class="timer-center"><div class="timer-context">${p==='complete'?`${g.records.filter(hasData).length} reps recorded`:g.recovery?`After ${e(s?.label||'this rep')}`:e(timerContext(g,s))}</div><div class="big-timer ${p==='complete'?'clock-complete':''}" data-main-clock>00:00<span class="fraction">.00</span></div></div><div class="timer-actions">${actions}</div><div class="timer-foot"><div class="upnext">${upNext(g)}</div>${p==='ready'||p==='complete'?'':`<button class="small-link" data-action="next-rep">Skip rep</button>`}</div></section>`;}
function timerCaption(g){return '';}
function sectionMembers(g,r,members){if(!sortPref()||g.completed||r.closed)return members;const key=a=>r.skipped.includes(a.id)?2:r.finishes[a.id]?1:0;return members.map((a,i)=>[a,i]).sort((x,y)=>key(x[0])-key(y[0])||(key(x[0])===1?r.finishes[x[0].id].at-r.finishes[y[0].id].at:x[1]-y[1])).map(x=>x[0]);}
function athleteRow(g,r,a){const f=r.finishes[a.id],skip=r.skipped.includes(a.id),planned=(r.modSkipped||[]).includes(a.id),started=r.starts[a.id]!=null,live=started&&!f&&!skip,closed=g.completed||r.closed,plan=athletePlan(g,a,r.index),splits=(r.splits||{})[a.id]||[],pk=(g.packs||[]).find(p=>p.id===a.pack),id=e(a.id),name=e(a.name);
  const canSplit=live&&!closed&&splits.length<splitCapacity(getStep(g,r.index)),tag=g.mode==='planned'&&plan.modified&&!plan.skip?`<span class="mod-tag">${fmtDist(plan.distance)}</span>`:'';
  const time=f?formatTime(f.ms):live&&!closed?formatTime(elapsed({start:r.starts[a.id]})):skip?(planned?'Skip':'DNS'):'—';
  let main='';
  if(f)main=`<button class="btn recorded" data-action="runner-menu" data-athlete="${id}" aria-label="Edit time for ${name}">${icon('check',17)}</button>`;
  else if(skip)main='';
  else if(closed)main=btn('Enter','runner-menu',{class:'ghost',attrs:`data-athlete="${id}"`});
  else if(started)main=btn('Finish','finish',{class:'finish',attrs:`data-athlete="${id}" aria-label="Finish ${name}"`});
  else main=btn('Start','start-one',{attrs:`data-athlete="${id}" aria-label="Start ${name}"`});
  const split=canSplit?`<button class="btn split-btn" data-action="split" data-athlete="${id}" aria-label="Take a split for ${name}">${icon('flag',17)}</button>`:'';
  return `<div class="athlete-swipe ${pk?'has-pack':''}" data-athlete-row="${id}" ${pk?`style="--pack:${packColor(g,pk)}"`:''}><button class="swipe-delete" data-action="delete-athlete" data-athlete="${id}" aria-label="Delete ${name}">${icon('trash',18)}<span>Delete</span></button><div class="athlete-row ${f||skip?'done':''}"><button class="drag-handle" data-drag="${id}" aria-label="Drag to reorder ${name}">${icon('grip',16)}</button><div class="athlete-name" data-action="runner-menu" data-athlete="${id}"><div class="name-line"><strong>${name}</strong>${tag}</div>${(splits.length||goalTagHtml(g,a,r.index))?`<div class="split-line">${goalTagHtml(g,a,r.index)}${splits.map(sp=>`<span class="split-time">${shortTime(sp.ms)}</span>`).join('')}</div>`:''}</div><span class="athlete-time ${!started&&!f?'empty':''} ${f?'final':''}${goalClass(g,a,r.index,f)}" ${live&&!closed?`data-athlete-clock="${id}"`:''}>${time}</span>${split}${main}</div></div>`;}
function packHead(g,r,p,members){const closed=g.completed||r.closed,ready=members.filter(a=>r.starts[a.id]==null&&!r.finishes[a.id]&&!r.skipped.includes(a.id)),running=members.filter(a=>isLive(r,a.id)),cap=splitCapacity(getStep(g,r.index)),splittable=running.filter(a=>((r.splits||{})[a.id]||[]).length<cap),at=`data-pack="${e(p.id)}"`;
  return `<div class="pack-head" style="--pack:${packColor(g,p)}"><span class="pack-name"><b>${e(p.name)}</b><small>${members.length}</small></span><span class="pack-actions">${closed?'':`${ready.length?btn(`Start ${ready.length}`,'start-pack',{attrs:at}):''}${splittable.length?`<button class="btn split-btn" data-action="split-pack" ${at} aria-label="Split ${e(p.name)}">${icon('flag',17)}</button>`:''}${running.length?btn(`Finish ${running.length}`,'finish-pack',{class:'finish',attrs:at}):''}`}<button class="btn icon-btn ghost" data-action="pack-menu" ${at} aria-label="Options for ${e(p.name)}">${icon('more',18)}</button></span></div>`;}
function athletesCard(g){const r=currentRep(g),count=Object.keys(r.finishes).length,closed=g.completed||r.closed,packs=g.packs||[],cap=splitCapacity(getStep(g));
  const canSplitAll=!closed&&g.athletes.some(a=>isLive(r,a.id)&&((r.splits||{})[a.id]||[]).length<cap);
  const secs=packs.length?[...packs.map(p=>({pack:p,members:g.athletes.filter(x=>x.pack===p.id)})),{pack:null,members:g.athletes.filter(x=>!packs.some(p=>p.id===x.pack))}]:[{pack:null,members:g.athletes}];
  const body=secs.map(sec=>{if(!sec.pack&&packs.length&&!sec.members.length)return `<div class="athlete-section" data-section data-pack=""></div>`;const head=sec.pack?packHead(g,r,sec.pack,sec.members):packs.length?`<div class="pack-head others"><span class="pack-name"><b>No pack</b><small>${sec.members.length}</small></span></div>`:'';const rows=sec.members.length?sectionMembers(g,r,sec.members).map(a=>athleteRow(g,r,a)).join(''):sec.pack?'<div class="empty-pack">No runners yet. Drag one here, or use a runner’s menu.</div>':'';return `<div class="athlete-section" data-section data-pack="${sec.pack?e(sec.pack.id):''}">${head}${rows}</div>`;}).join('');
  return `<section class="card athletes-card"><div class="card-head"><h2>Runners</h2><div class="head-actions">${canSplitAll?btn('Split all','split-all',{icon:'flag',class:'split-all'}):''}<span class="count-pill">${count} / ${g.athletes.length} timed</span><button class="btn icon-btn ghost" data-action="list-options" aria-label="Runner list options">${icon('settings',18)}</button></div></div><div class="athlete-list" data-has-packs="${packs.length?1:0}">${body}</div>${captureList(g,r)}</section>`;}
function captureList(g,r){if(!r.unassigned.length)return '';const firstStart=Math.min(...Object.values(r.starts));return `<div class="unassigned"><h3>${r.unassigned.length} finish${r.unassigned.length===1?'':'es'} to assign</h3>${r.unassigned.map(c=>`<div class="capture-row"><span>${formatTime(c.at-firstStart)}</span><label class="sr-only" for="capture-${e(c.id)}">Athlete for captured finish</label><select class="form-control" id="capture-${e(c.id)}" data-capture="${e(c.id)}" data-group="${e(g.id)}" data-rep="${r.index}"><option value="">Choose runner</option>${g.athletes.filter(a=>r.starts[a.id]!=null&&!r.finishes[a.id]&&!r.skipped.includes(a.id)&&r.starts[a.id]<=c.at).map(a=>`<option value="${e(a.id)}">${e(a.name)}</option>`).join('')}</select><button class="btn icon-btn ghost" data-action="remove-capture" data-group="${e(g.id)}" data-rep="${r.index}" data-capture-id="${e(c.id)}" aria-label="Remove this unassigned finish">${icon('close',16)}</button></div>`).join('')}</div>`;}
function planRows(steps,currentIndex=-1,completed=false){return steps.map((s,i)=>`${i===0||steps[i-1].blockIndex!==s.blockIndex?`<div class="plan-block">${e(s.blockTitle)}</div>`:''}<div class="plan-row ${completed||i<currentIndex?'done':i===currentIndex?'current':''}"><span class="plan-number">${i+1}</span><strong>${e(s.label)}</strong><span>${completed||i<currentIndex?icon('check',16):i===currentIndex?'Now':''}</span></div>${s.restAfterSeconds>0?`<div class="plan-rest">${icon('clock',13)} ${restText(s.restAfterSeconds)} recovery</div>`:''}`).join('');}
function workoutCard(g){const plan=getPlan(g);return `<details class="card workout-details"><summary><span><strong>${g.mode==='free'?'Free timing':'Workout sequence'}</strong><small>${g.mode==='free'?'Open-ended reps':`${plan.length} runs · ${new Set(plan.map(s=>s.blockIndex)).size} blocks`}</small></span><span class="summary-toggle">${icon('plus',18)}</span></summary><div class="workout-card"><div class="section-top"><h2>${g.mode==='free'?'Your pace':'Every step'}</h2><button class="small-link" data-action="edit-group" data-group="${e(g.id)}">Load / edit</button></div>${g.mode==='free'?`<p class="form-help">Time as many reps as you need, with ${restText(g.restSeconds)} recovery.</p>`:`<div class="plan-list">${planRows(plan,g.repIndex,g.completed)}</div>`}</div></details>`;}
function recoveryCard(g){return `<details class="card workout-details"><summary><span><strong>Recovery controls</strong><small>${g.recoveryMode==='auto'?'Starts after last recorded finish':'Starts when you tap'}</small></span><span class="summary-toggle">${icon('settings',18)}</span></summary><div class="recovery-card"><div class="segmented" aria-label="Recovery mode"><button class="${g.recoveryMode==='auto'?'selected':''}" data-action="recovery-mode" data-mode="auto" aria-pressed="${g.recoveryMode==='auto'}">Automatic</button><button class="${g.recoveryMode==='manual'?'selected':''}" data-action="recovery-mode" data-mode="manual" aria-pressed="${g.recoveryMode==='manual'}">Manual</button></div><p>${g.recoveryMode==='auto'?'Starts after the last participating runner is recorded. Start rest manually any time.':'The recovery countdown waits for your tap.'} Your next rep always waits for you.</p><div class="recovery-options">${btn('Start rest','start-recovery',{disabled:!!g.recovery||g.completed})}${btn('+30 sec','add-rest',{disabled:!g.recovery,attrs:'data-seconds="30"'})}</div></div></details>`;}
function liveView(){const g=current();return intro(session.name,'',btn('','undo',{icon:'undo',class:'ghost',disabled:!history.length,attrs:'aria-label="Undo last action" title="Undo last action"'})+btn('','edit-group',{icon:'edit',class:'icon-btn',attrs:`data-group="${e(g.id)}" aria-label="Load workout" title="Load workout"`}))+groupTabs()+workoutStrip(g)+`<div class="live-grid"><div class="center-column"><div class="timer-sticky">${timerCard(g)}</div>${athletesCard(g)}</div><aside class="side-column">${workoutCard(g)}${recoveryCard(g)}</aside></div>`;}
function resultTable(g){const recordIndexes=g.records.filter(hasData).map(r=>r.index),n=g.mode==='free'?Math.max(1,g.repIndex+1):total(g);return `<div class="table-scroll"><table><thead><tr><th scope="col">Athlete</th>${hasGoals(g)?'<th scope="col">Goal</th>':''}${Array.from({length:n},(_,i)=>{const s=getStep(g,i);return `<th scope="col" title="${e(s?.blockTitle)}">${e(s?.label||'Rep')}<small>Rep ${i+1}</small></th>`;}).join('')}<th scope="col">Recorded</th></tr></thead><tbody>${g.athletes.map(a=>{const values=g.records.map(r=>r.finishes[a.id]?.ms).filter(v=>v!=null),pk=(g.packs||[]).find(p=>p.id===a.pack);return `<tr><td>${e(a.name)}${pk?`<span class="pack-tag" style="--pack:${packColor(g,pk)}">${e(pk.name)}</span>`:''}</td>${hasGoals(g)?`<td class="goal-cell">${e(goalString(g,a))}</td>`:''}${Array.from({length:n},(_,i)=>{const r=g.records.find(r=>r.index===i),f=r?.finishes[a.id],at=`data-action="edit-time" data-group="${e(g.id)}" data-athlete="${e(a.id)}" data-rep="${i}"`;return `<td>${f?`<button class="time-cell${goalClass(g,a,i,f)}" ${at} title="${f.manual?'Manually entered':'Stopwatch time'} · tap to edit">${formatTime(f.ms)}${f.manual?'*':''}</button>`:r?.skipped.includes(a.id)?`<button class="time-cell muted" ${at}>${(r.modSkipped||[]).includes(a.id)?'Skip':'DNS'}</button>`:recordIndexes.includes(i)?`<button class="time-cell missing-cell" ${at}>Missing</button>`:'<span class="empty-cell">—</span>'}${r?cellMeta(g,r,a):''}</td>`;}).join('')}<td>${values.length} / ${n}</td></tr>`;}).join('')}</tbody></table></div>`;}
function resultsView(){const records=session.groups.flatMap(g=>g.records),times=records.reduce((n,r)=>n+Object.keys(r.finishes).length,0),missing=session.groups.reduce((n,g)=>n+g.records.filter(hasData).reduce((n,r)=>n+g.athletes.filter(a=>!r.finishes[a.id]&&!r.skipped.includes(a.id)).length,0),0);return intro('Results',e(session.name),btn('Save','save-session',{icon:'save'})+btn('CSV','export',{icon:'download',class:'primary',attrs:'aria-label="Export CSV"'}),'intro-results')+sendRow()+`<div class="result-summary"><div class="card summary-stat"><span>Recorded</span><strong>${times}</strong></div><div class="card summary-stat"><span>Runners</span><strong>${session.groups.reduce((n,g)=>n+g.athletes.length,0)}</strong></div><div class="card summary-stat"><span>Missing</span><strong>${missing}</strong></div></div>${session.groups.map(g=>`<section class="card results-card"><div class="card-head"><div><h2>${e(g.name)}</h2><p>${g.mode==='free'?'Free timing':`${total(g)} runs · ${new Set(getPlan(g).map(s=>s.blockIndex)).size} blocks`}</p></div><button class="small-link" data-action="return-group" data-group="${e(g.id)}">Timer</button></div>${resultTable(g)}${g.records.map(r=>captureList(g,r)).join('')}</section>`).join('')}<p class="results-note">Swipe across for every rep. Tap any time to correct it.<br><b>*</b> Manual entry · <b>DNS</b> Did not run · <b>Skip</b> Planned skip.<br>The CSV matches this layout. <button class="small-link inline" data-action="export-detail">Detailed CSV</button> has one row per time, in seconds.</p>`;}
function setupView(){const archives=archiveRead();return intro('Workouts & groups','Build the practice you actually run.',btn('Load practice','practice-modal',{icon:'download',class:'primary'})+btn('New group','add-group',{icon:'plus'}))+`<div class="setup-content"><section class="card setup-panel"><div class="setup-group-list">${session.groups.map(g=>`<div class="setup-group"><div><h3>${e(g.name)}</h3><p>${g.mode==='free'?'Free timing':`${total(g)} runs · ${new Set(getPlan(g).map(s=>s.blockIndex)).size} blocks`} · ${g.athletes.length} runners</p></div>${btn('Load / edit','edit-group',{attrs:`data-group="${e(g.id)}"`})}${session.groups.length>1?btn('','delete-group',{icon:'trash',class:'ghost danger icon-btn',attrs:`data-group="${e(g.id)}" aria-label="Delete ${e(g.name)}" title="Delete group"`}):''}</div>`).join('')}</div><p class="form-help">Paste a tempo, ladder, repeats, and recovery breaks into one workout. Review the steps before loading.</p></section><section class="card setup-panel"><h2>Session details</h2><form id="session-form"><div class="field"><label for="session-name">Name</label><input class="form-control" id="session-name" name="name" maxlength="90" value="${e(session.name)}" required></div><div class="form-actions"><button class="btn primary" type="submit">Save name</button></div></form></section><section class="card setup-panel"><h2>Google Sheet</h2><p>${sheetOn()?'Connected. Results can post to your coach sheet and today’s practice can load from it.':'Not connected. Connect once to load practices from the sheet and send results to it.'}</p><div class="form-actions">${btn(sheetOn()?'Settings':'Connect','sheet-settings',{icon:'settings'})}${sheetOn()?btn('Send results now','send-sheet',{icon:'download'}):''}</div><p class="form-help" data-sheet-status>${e(sheetStatus||'')}</p></section><section class="card setup-panel"><h2>Save & export</h2><p>Results save in this browser. Export a separate copy for your records or Google Sheets.</p><div class="form-actions">${btn('Save session','save-session',{icon:'save'})}${btn('Export CSV','export',{icon:'download'})}${btn('Detailed CSV','export-detail',{icon:'download'})}${btn(soundOn?'Sound on':'Recovery sound','toggle-sound',{icon:'bell'})}${btn('New session','new-session',{icon:'plus'})}</div></section><section class="card setup-panel"><h2>Saved sessions</h2><div class="saved-sessions">${archives.length?archives.map(s=>`<div class="archive-row"><div><strong>${e(s.name)}</strong><small>${new Date(s.createdAt).toLocaleDateString()} · ${s.groups.reduce((n,g)=>n+g.records.reduce((n,r)=>n+Object.keys(r.finishes).length,0),0)} times</small></div><div class="form-actions">${btn(s.id===session.id?'Current':'Open','open-archive',{disabled:s.id===session.id,attrs:`data-session="${e(s.id)}"`})}${btn('CSV','export-archive',{attrs:`data-session="${e(s.id)}"`})}</div></div>`).join(''):'<p class="muted">No saved sessions yet.</p>'}</div></section><p class="results-note">This is a phone layout prototype. Native iOS / Android installation, background alerts, and direct Sheets sync are future steps.</p></div>`;}

function render(){lastPhase=phase(current());$('#app').innerHTML=shell(view==='live'?liveView():view==='results'?resultsView():setupView());updateClocks();fitUpcoming();centerStrip();document.fonts?.ready.then(fitUpcoming);}
function centerStrip(){const strip=document.querySelector('.workout-strip'),cur=strip?.querySelector('.wl.current');if(cur)strip.scrollLeft=cur.offsetLeft-(strip.clientWidth-cur.offsetWidth)/2;}

let clockTick=0;
function updateClocks(){const now=Date.now();if(++clockTick%8===0)fitUpcoming();for(const g of session.groups){const p=phase(g,now);const badge=document.querySelector(`[data-group-phase="${g.id}"]`);if(badge)badge.textContent=tabStatus(g,now);const tab=document.querySelector(`[data-group-tab="${g.id}"]`);if(tab)tab.classList.toggle('attention',tabAttention(g,now));if(g.recovery&&recoveryRemaining(g,now)<=0){const id=g.id+':'+g.recovery.startedAt;if(!alerted.has(id)){alerted.add(id);if(now-(g.recovery.startedAt+g.recovery.durationMs)<3000){toast(`${g.name}: recovery complete. Ready when you are.`);beep();}}}}
  const g=current(),r=currentRep(g),p=phase(g,now);if(view==='live'&&p!==lastPhase&&!drag&&!swipe?.active){render();return;}
  const main=$('[data-main-clock]');if(main){if(p==='complete'){main.textContent='Workout Complete!';}else if(g.recovery){const remain=recoveryRemaining(g,now);main.textContent=remain>0?`${String(Math.floor(Math.ceil(remain/1000)/60)).padStart(2,'0')}:${String(Math.ceil(remain/1000)%60).padStart(2,'0')}`:'Ready';main.classList.toggle('rest-ready',remain===0);}else{const starts=Object.values(r.starts);const outstanding=g.athletes.some(a=>r.starts[a.id]!=null&&!r.finishes[a.id]&&!r.skipped.includes(a.id));const finishes=Object.values(r.finishes);const end=outstanding?now:finishes.length?Math.max(...finishes.map(f=>f.at)):now;const t=starts.length?formatTime(Math.max(0,end-Math.min(...starts))):'00:00.00';const [whole,fraction]=t.split('.');main.innerHTML=`${whole}<span class="fraction">.${fraction}</span>`;}}
  for(const el of document.querySelectorAll('[data-athlete-clock]'))el.textContent=formatTime(elapsed({start:r.starts[el.dataset.athleteClock]},now));
}
function beep(){if(!soundOn)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();const o=audioContext.createOscillator(),gain=audioContext.createGain();o.connect(gain);gain.connect(audioContext.destination);o.frequency.value=800;gain.gain.setValueAtTime(.08,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.45);o.start();o.stop(audioContext.currentTime+.45);}catch{}}
function modal(title,body,submit){const dialog=$('#modal');if(dialog.open)dialog.close();dialog.innerHTML=`<div class="modal-head"><h2>${e(title)}</h2><button class="btn ghost icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;dialog.showModal();const form=dialog.querySelector('form');if(form&&submit)form.addEventListener('submit',event=>{event.preventDefault();try{submit(new FormData(form));}catch(err){const error=dialog.querySelector('#group-error')||dialog.querySelector('.error-text');if(error)error.textContent=err.message;else toast(err.message);}});}
function closeModal(){$('#modal').close();}
function parseTime(value){const s=value.trim();if(!/^(?:\d+:)?\d+(?:\.\d{1,3})?$/.test(s))throw new Error('Use seconds (64.32) or minutes:seconds (1:04.32).');const parts=s.split(':').map(Number);if(parts.length===2&&parts[1]>=60)throw new Error('Seconds after the colon must be less than 60.');const ms=(parts.length===2?parts[0]*60+parts[1]:parts[0])*1000;if(ms>86400000)throw new Error('That time is too long.');return Math.round(ms);}
function editTime(groupId,athleteId,repIndex,full=false){const g=getGroup(session,groupId),a=g.athletes.find(a=>a.id===athleteId),r=g.records.find(r=>r.index===(repIndex??g.repIndex)),f=r.finishes[a.id],plan=athletePlan(g,a,r.index),packs=g.packs||[];
  const extras=full?`<div class="menu-list">${g.mode==='planned'?btn('Change this runner’s workout','mods-sheet',{icon:'edit',attrs:`data-athlete="${e(a.id)}"`}):''}${packs.length?`<div class="field"><label for="move-pack">Pack</label><select id="move-pack" class="form-control" data-move-pack="${e(a.id)}"><option value="">No pack</option>${packs.map(p=>`<option value="${e(p.id)}" ${a.pack===p.id?'selected':''}>${e(p.name)}</option>`).join('')}</select></div>`:''}${g.mode==='planned'?btn('Goal paces','goals-sheet',{icon:'flag',attrs:`data-athlete="${e(a.id)}"`}):''}${btn('Delete runner','delete-athlete',{class:'danger',icon:'trash',attrs:`data-athlete="${e(a.id)}"`})}</div>`:'';
  modal(a.name,`<p>${e(g.name)} · ${e(repLabel(g,r.index))}${g.mode==='planned'&&plan.modified&&!plan.skip?`<br>Running ${fmtDist(plan.distance)} this rep (plan: ${fmtDist(plan.planned)}).`:''}${plan.skip?'<br>Planned skip for this rep.':''}<br>Enter a known finish time. Recovery keeps running.</p><form><div class="field"><label for="manual-time">Time</label><input id="manual-time" class="form-control mono" name="time" inputmode="decimal" placeholder="1:04.32 or 64.32" value="${f?formatTime(f.ms):''}" autocomplete="off" required ${full?'':'autofocus'}><small>Seconds or minutes:seconds. Manual entries are marked in results.</small></div>${r.splits?.[a.id]?.length?`<div class="field">${btn('Clear '+r.splits[a.id].length+' split'+(r.splits[a.id].length===1?'':'s'),'clear-splits',{class:'ghost danger',attrs:`type="button" data-group="${e(g.id)}" data-athlete="${e(a.id)}" data-rep="${r.index}"`})}</div>`:''}<div class="error-text" role="alert"></div><div class="modal-actions">${!f&&!r.skipped.includes(a.id)?btn('Did not run','skip-athlete',{class:'ghost',attrs:`type="button" data-group="${e(g.id)}" data-athlete="${e(a.id)}" data-rep="${r.index}"`}):''}<button class="btn primary" type="submit">Save time</button></div></form>${extras}`,data=>{const ms=parseTime(data.get('time'));if(dispatch({type:'SET_TIME',groupId:g.id,athleteId:a.id,repIndex:r.index,ms},'Time saved. Recovery timing is unchanged.'))closeModal();});}
function modsSheet(ids,title){const g=current(),members=g.athletes.filter(a=>ids.includes(a.id)),steps=getPlan(g).slice(g.repIndex,g.repIndex+100),distances=[...new Set(steps.map(s=>s.distance))];
  const pre=i=>{const mods=members.map(a=>a.mods?.[i]||null),first=JSON.stringify(mods[0]);return mods.every(m=>JSON.stringify(m)===first)?mods[0]:null;};
  modal(title,`<p>Leave a row blank to follow the workout. Type a distance to change it, or tick Skip.${getPlan(g).length-g.repIndex>100?' Showing the next 100 runs.':''}</p><form id="mods-form"><div class="quick-fill"><span>Change every</span><select id="qf-from" class="form-control">${distances.map(d=>`<option value="${d}">${fmtDist(d)}</option>`).join('')}</select><span>to</span><input id="qf-to" class="form-control" inputmode="decimal" placeholder="meters" aria-label="New distance in meters"><button type="button" class="btn" data-action="quick-fill">Fill</button></div><div class="mod-list">${steps.map(s=>{const m=pre(s.index);return `<div class="mod-row ${s.index===g.repIndex?'now':''}"><span class="mod-label"><b>${s.index+1}</b>${e(s.label)}</span><input class="form-control mod-dist" data-step="${s.index}" data-planned="${s.distance}" inputmode="decimal" placeholder="${s.distance}" value="${m?.distance??''}" aria-label="Distance for run ${s.index+1}"><label class="mod-skip"><input type="checkbox" data-skip="${s.index}" ${m?.skip?'checked':''}>Skip</label></div>`;}).join('')}</div><div class="error-text" role="alert"></div><div class="modal-actions"><button type="button" class="btn ghost" data-action="clear-mod-rows">Clear all</button><button class="btn primary" type="submit">Save</button></div></form>`,()=>{const changes={};for(const input of document.querySelectorAll('#modal .mod-dist')){const i=Number(input.dataset.step),skip=document.querySelector(`#modal [data-skip="${i}"]`).checked,d=parseDist(input.value);changes[i]=skip?{skip:true}:d!=null&&d!==Number(input.dataset.planned)?{distance:d}:null;}if(dispatch({type:'SET_MODS',athleteIds:ids,changes},'Workout updated.'))closeModal();});}
const packRow=p=>`<div class="pack-row" data-pack-row="${e(p.id)}"><input class="form-control" value="${e(p.name)}" maxlength="24" placeholder="Pack name" aria-label="Pack name"><button type="button" class="btn icon-btn ghost" data-action="remove-pack-row" aria-label="Remove this pack">${icon('close',16)}</button></div>`;
function refreshAssign(initial={}){const rows=[...document.querySelectorAll('#modal [data-pack-row]')];document.querySelectorAll('#modal [data-assign]').forEach(sel=>{const keep=sel.value||initial[sel.dataset.assign]||'';sel.innerHTML='<option value="">No pack</option>'+rows.map((row,i)=>`<option value="${e(row.dataset.packRow)}">${e(row.querySelector('input').value.trim()||`Pack ${i+1}`)}</option>`).join('');sel.value=rows.some(r=>r.dataset.packRow===keep)?keep:'';});}
function packsModal(){const g=current(),packs=g.packs||[];modal('Timing packs',`<p>A pack is a group of runners you can start, split, or finish together. Runners can move between packs at any time.</p><form id="packs-form"><div id="pack-rows">${packs.map(packRow).join('')}</div><button type="button" class="btn" data-action="add-pack-row">${icon('plus')}Add pack</button><div class="assign-list">${g.athletes.map(a=>`<div class="assign-row"><span>${e(a.name)}</span><select class="form-control" data-assign="${e(a.id)}" aria-label="Pack for ${e(a.name)}"></select></div>`).join('')}</div><div class="error-text" role="alert"></div><div class="modal-actions"><button class="btn primary" type="submit">Save packs</button></div></form>`,()=>{const list=[...document.querySelectorAll('#modal [data-pack-row]')].map(row=>({id:row.dataset.packRow,name:row.querySelector('input').value})),assignments={};document.querySelectorAll('#modal [data-assign]').forEach(sel=>{assignments[sel.dataset.assign]=sel.value||null;});if(dispatch({type:'SET_PACKS',packs:list,assignments},'Packs saved.'))closeModal();});refreshAssign(Object.fromEntries(g.athletes.map(a=>[a.id,a.pack||''])));}
function packMenu(packId){const g=current(),p=(g.packs||[]).find(x=>x.id===packId);if(!p)return;const n=g.athletes.filter(a=>a.pack===p.id).length;modal(p.name,`<p>${n} runner${n===1?'':'s'} in this pack.</p><div class="stack">${g.mode==='planned'?btn('Change this pack’s workout','pack-mods',{icon:'edit',attrs:`data-pack="${e(p.id)}"`}):''}${(g.packs||[]).length>1?`<div class="row2">${btn('Move up','move-pack',{attrs:`data-pack="${e(p.id)}" data-dir="-1"`})}${btn('Move down','move-pack',{attrs:`data-pack="${e(p.id)}" data-dir="1"`})}</div>`:''}${btn('Rename or reshape packs','packs-modal',{icon:'users'})}${btn('Disband this pack','disband-pack',{class:'danger',attrs:`data-pack="${e(p.id)}"`})}</div>`);}
function listOptions(){modal('Runner list',`<div class="switch-row"><div><strong>Finished runners move to the bottom</strong><small>Keeps the runners still on the track at the top.</small></div><button class="switch" role="switch" aria-checked="${sortPref()}" data-action="toggle-sort" aria-label="Move finished runners to the bottom"><span></span></button></div><div class="switch-row"><div><strong>Show goal paces on runners</strong><small>A small goal under each name. Finished times turn green or red either way.</small></div><button class="switch" role="switch" aria-checked="${session.prefs?.showGoals!==false}" data-action="toggle-goals" aria-label="Show goal paces"><span></span></button></div><div class="stack">${btn('Timing packs','packs-modal',{icon:'users'})}</div><form id="add-runner-form" class="add-runner"><label for="new-runner">Add a runner</label><div class="row"><input id="new-runner" class="form-control" name="name" maxlength="40" placeholder="Name" autocomplete="off"><button class="btn primary" type="submit">Add</button></div><div class="error-text" role="alert"></div></form><p class="modal-hint">Tip: slide a runner to the right to delete, or drag the grip on the left to reorder.</p>`,data=>{if(dispatch({type:'ADD_ATHLETE',name:String(data.get('name')||'')},'Runner added.'))closeModal();});}
function resetMenu(){const g=current(),r=currentRep(g),hasRep=Object.keys(r.starts).length||Object.keys(r.finishes).length||r.unassigned.length;if(!g.recovery&&!hasRep){toast('Nothing to reset yet.');return;}modal('Stop or reset',`${g.recovery?`<div class="reset-block"><h3>Rest timer</h3><p>Restart the countdown from the full rest, or stop it altogether.</p><div class="stack">${btn('Restart rest','reset-rest',{icon:'reset'})}${btn('Stop rest','stop-rest',{icon:'stop'})}</div></div>`:''}${hasRep?`<div class="reset-block"><h3>This rep</h3><p>Clears every start, finish, and split recorded for this rep so you can start over.${g.recovery?' The rest timer is cancelled too.':''}</p>${btn('Reset rep clock','reset-rep',{icon:'reset',class:'danger'})}</div>`:''}<div class="modal-actions">${btn('Cancel','close-modal')}</div>`);}
function confirmDeleteAthlete(id){const g=current(),a=g.athletes.find(x=>x.id===id);if(!a)return;modal(`Remove ${a.name}?`,`<p>${e(a.name)} will be removed from this group, along with any times recorded so far. Tap Undo right after to bring them back.</p><div class="modal-actions">${btn('Keep','close-modal')}<button class="btn primary" id="confirm-del">Remove</button></div>`);$('#confirm-del').onclick=()=>{if(dispatch({type:'DELETE_ATHLETE',athleteId:id},`${a.name} removed. Tap Undo to restore.`))closeModal();};}
function confirmDeleteGroup(id){const g=getGroup(session,id);if(session.groups.length<=1){toast('A session needs at least one group.');return;}modal(`Delete ${g.name}?`,`<p>This removes the group, its runners, and all of its times from this session. Tap Undo right after to bring it back.</p><div class="modal-actions">${btn('Keep','close-modal')}<button class="btn primary" id="confirm-del-group">Delete group</button></div>`);$('#confirm-del-group').onclick=()=>{if(dispatch({type:'DELETE_GROUP',groupId:id},`${g.name} deleted. Tap Undo to restore.`))closeModal();};}
function groupMenu(id){const g=getGroup(session,id);modal(g.name,`<div class="stack">${btn('Load / edit workout','edit-group',{icon:'edit',attrs:`data-group="${e(g.id)}"`})}${btn('Timing packs','packs-modal',{icon:'users'})}${btn('Delete group','delete-group',{class:'danger',icon:'trash',attrs:`data-group="${e(g.id)}"`})}</div>`);}
function groupWorkoutText(g){if(g?.workoutText)return g.workoutText;if(!g)return SAMPLE_WORKOUT;return `${g.sets} sets of ${g.repsPerSet}x${g.distance} ${g.restSeconds}s rest, ${g.setRestSeconds}s between sets`;}
function updateWorkoutPreview(){const input=$('#workout-text'),preview=$('#workout-preview');if(!input||!preview)return;try{const parsed=parseWorkout(input.value);preview.innerHTML=`<div class="preview-summary">${icon('check',16)} ${parsed.steps.length} runs · ${parsed.blocks.length} blocks · ${parsed.steps.reduce((n,s)=>n+s.distance,0).toLocaleString()}m total</div><div class="plan-preview">${planRows(parsed.steps)}</div>`;preview.classList.remove('invalid');}catch(err){preview.innerHTML=`<p class="error-text">${e(err.message)}</p>`;preview.classList.add('invalid');}}
function editGroup(id,copy=false){const source=id?getGroup(session,id):null,g=copy?null:source;if(g&&g.records.some(hasData)){modal('This workout is underway',`<p>Your recorded times stay with this workout. Load a different workout into a new group using the same roster, or keep timing this one.</p><div class="modal-actions">${session.groups.length>1?btn('Delete group','delete-group',{class:'ghost danger',attrs:`data-group="${e(g.id)}"`}):''}${btn('Keep timing','close-modal')}${btn('New workout','copy-group',{class:'primary',attrs:`data-group="${e(g.id)}"`})}</div>`);return;}
  const mode=g?.mode||'planned',names=(source?.athletes||createSession().groups[0].athletes).map(a=>a.name).join('\n');
  modal(g?'Load workout':'New workout group',`<form id="group-form"><div class="form-grid"><div class="field wide"><label for="group-name">Group name</label><input id="group-name" class="form-control" name="name" value="${e(copy?source.name+' · new':g?.name||'')}" placeholder="Distance crew" maxlength="50" required></div><div class="field wide"><label for="group-mode">Timing style</label><select id="group-mode" class="form-control" name="mode"><option value="planned" ${mode==='planned'?'selected':''}>Planned workout</option><option value="free" ${mode==='free'?'selected':''}>Free timing</option></select></div><div class="field wide"><label for="group-sheetcolor">Color on the results sheet</label><select id="group-sheetcolor" class="form-control" name="sheetColor">${[['blue','Blue (distance)'],['red','Red (mid distance)'],['yellow','Yellow (freshmen)']].map(([v,l])=>`<option value="${v}" ${(g?.sheetColor||'blue')===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field wide" id="planned-fields" ${mode==='free'?'hidden':''}><div class="section-top"><label for="workout-text">Paste your workout</label><button type="button" class="small-link" data-action="sample-workout">Use example</button></div><textarea id="workout-text" class="form-control workout-editor" name="workoutText" rows="6" maxlength="8000" spellcheck="false">${e(groupWorkoutText(g))}</textarea><small>Distances in meters or km. Use “5x150 90s rest” for repeats and “4min break” between blocks. Add “split 400” (or “splits every 200”) to record mid-run splits, e.g. “800 split 400 2min rest”.</small><div id="workout-preview" aria-live="polite"></div></div><div class="field wide" id="free-fields" ${mode==='planned'?'hidden':''}><div class="form-grid"><div class="field"><label for="distance">Distance (m)</label><input class="form-control" id="distance" name="distance" type="number" min="1" max="100000" value="${g?.distance||400}" required></div><div class="field"><label for="rest">Recovery (sec)</label><input class="form-control" id="rest" name="restSeconds" type="number" min="0" max="86400" value="${g?.restSeconds??60}" required></div></div></div><div class="field wide"><label for="recovery-mode">Recovery begins</label><select id="recovery-mode" class="form-control" name="recoveryMode"><option value="auto" ${g?.recoveryMode==='manual'?'':'selected'}>After last recorded finish</option><option value="manual" ${g?.recoveryMode==='manual'?'selected':''}>When I tap Start rest</option></select></div><div class="field wide"><details class="roster-details"><summary>Runners · edit roster</summary><label for="roster" class="sr-only">Runners, one per line</label><textarea class="form-control" id="roster" name="roster" rows="6" maxlength="4000" required>${e(names)}</textarea><small>One runner per line.</small></details></div></div><div class="error-text" id="group-error" role="alert"></div><div class="modal-actions">${g&&session.groups.length>1?btn('Delete group','delete-group',{class:'ghost danger',attrs:`type="button" data-group="${e(g.id)}"`}):''}<button class="btn primary" type="submit">${g?'Load workout':'Create group'}</button></div></form>`,data=>{const values=Object.fromEntries(data);values.athleteNames=values.roster.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);delete values.roster;if(values.athleteNames.length>50)throw new Error('Use up to 50 runners per group.');if(values.mode==='planned'){parseWorkout(values.workoutText);}else values.workoutText='';if(dispatch({type:g?'UPDATE_GROUP':'ADD_GROUP',groupId:g?.id,values},'Workout loaded. Ready when you are.')){closeModal();view='live';render();}});
  updateWorkoutPreview();
}

function nextRep(){const g=current(),r=currentRep(g);if(g.completed)return;const missing=g.athletes.filter(a=>!r.finishes[a.id]&&!r.skipped.includes(a.id)).length;const advance=()=>{dispatch({type:'NEXT_REP'},g.mode==='planned'&&g.repIndex>=total(g)-1?'Workout complete.':'Next rep is ready. Tap Start all when you’re ready.');closeModal();};if(missing||r.unassigned.length){modal('Move to the next rep?',`<p>${missing?`${missing} runner${missing===1?' still needs':'s still need'} a time. `:''}${r.unassigned.length?`${r.unassigned.length} captured finish${r.unassigned.length===1?' is':'es are'} unassigned. `:''}You can correct these in Results later. Any running stopwatches for this rep will close.</p><div class="modal-actions">${btn('Keep timing','close-modal')}<button class="btn primary" id="confirm-next">Continue</button></div>`);$('#confirm-next').onclick=advance;}else advance();}
function download(s,detail=false){const csv='\uFEFF'+(detail?exportDetailCsv(s):exportCsv(s));const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`terrier-timing-${s.name.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}-${new Date(s.createdAt).toLocaleDateString('en-CA')}${detail?'-detail':''}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('CSV exported. Import it into Google Sheets when you’re ready.');}
function saveArchive(show=true){try{const items=archiveRead().filter(s=>s.id!==session.id);items.unshift(clone(session));localStorage.setItem(ARCHIVE,JSON.stringify(items.slice(0,20)));if(show)toast('Session snapshot saved on this browser.');return true;}catch{toast('Couldn’t save a snapshot. Export a CSV to keep your results.');return false;}}

document.addEventListener('click',event=>{if(suppressClick){suppressClick=false;event.preventDefault();return;}const nav=event.target.closest('[data-view]');if(nav){view=nav.dataset.view;render();window.scrollTo({top:0,behavior:'instant'});return;}const target=event.target.closest('[data-action]');if(!target||target.disabled)return;const {action,athlete,group,rep,pack}=target.dataset;switch(action){
  case 'select-group':if(group===session.activeGroupId&&view==='live')groupMenu(group);else dispatch({type:'SELECT_GROUP',groupId:group});break;
  case 'runner-menu':editTime(session.activeGroupId,athlete,undefined,true);break;
  case 'list-options':listOptions();break;
  case 'toggle-sort':dispatch({type:'SET_PREF',key:'finishedToBottom',value:!sortPref()});target.setAttribute('aria-checked',String(sortPref()));break;
  case 'packs-modal':packsModal();break;
  case 'pack-menu':packMenu(pack);break;
  case 'start-pack':dispatch({type:'START_PACK',packId:pack});break;
  case 'finish-pack':dispatch({type:'FINISH_PACK',packId:pack});break;
  case 'split-pack':dispatch({type:'SPLIT_PACK',packId:pack});break;
  case 'disband-pack':{const g=current();if(dispatch({type:'SET_PACKS',packs:(g.packs||[]).filter(p=>p.id!==pack)},'Pack disbanded. Its runners are back in the main list.'))closeModal();break;}
  case 'mods-sheet':{const a=current().athletes.find(x=>x.id===athlete);if(a)modsSheet([a.id],`${a.name} · workout`);break;}
  case 'pack-mods':{const g=current(),p=(g.packs||[]).find(x=>x.id===pack);if(p)modsSheet(g.athletes.filter(a=>a.pack===p.id).map(a=>a.id),`${p.name} · workout`);break;}
  case 'quick-fill':{const from=$('#qf-from').value,to=$('#qf-to').value;try{if(parseDist(to)==null)throw new Error('Type the new distance first.');}catch(err){const box=$('#modal .error-text');if(box)box.textContent=err.message;break;}for(const input of document.querySelectorAll('#modal .mod-dist'))if(input.dataset.planned===from){input.value=to.trim().replace(/m$/i,'');document.querySelector(`#modal [data-skip="${input.dataset.step}"]`).checked=false;}break;}
  case 'clear-mod-rows':document.querySelectorAll('#modal .mod-dist').forEach(i=>{i.value='';});document.querySelectorAll('#modal [data-skip]').forEach(c=>{c.checked=false;});break;
  case 'add-pack-row':{const rows=document.querySelectorAll('#modal [data-pack-row]');if(rows.length>=8){toast('Use up to 8 packs.');break;}$('#pack-rows').insertAdjacentHTML('beforeend',packRow({id:`pack-${Date.now().toString(36)}${Math.random().toString(36).slice(2,5)}`,name:`Pack ${rows.length+1}`}));refreshAssign();break;}
  case 'remove-pack-row':target.closest('[data-pack-row]').remove();refreshAssign();break;
  case 'reset-menu':resetMenu();break;
  case 'reset-rep':if(dispatch({type:'RESET_REP'},'Rep reset. Ready to start again. Tap Undo to bring it back.'))closeModal();break;
  case 'reset-rest':if(dispatch({type:'RESET_REST'},'Rest restarted.'))closeModal();break;
  case 'stop-rest':if(dispatch({type:'RESET_REST',stop:true},'Rest stopped.'))closeModal();break;
  case 'delete-athlete':confirmDeleteAthlete(athlete);break;
  case 'delete-group':confirmDeleteGroup(group||session.activeGroupId);break;
  case 'export-detail':download(session,true);break;
  case 'practice-modal':practiceModal();break;
  case 'practice-example':$('#practice-text').value=PRACTICE_EXAMPLE;updatePracticePreview();break;
  case 'practice-fetch':fetchPractice(target.dataset.tab);break;
  case 'practice-load':loadPracticeText($('#practice-text').value,$('#practice-name').value.trim()||'Practice');break;
  case 'practice-save-template':{const text=$('#practice-text').value.trim(),name=$('#practice-name').value.trim();try{parsePractice(text);}catch(err){toast(err.message);break;}if(!name){toast('Give the template a name first.');break;}lsSet(TEMPLATES_KEY,[{name,text,savedAt:Date.now()},...templates().filter(t=>t.name!==name)].slice(0,30));practiceModal(text,name);toast('Template saved on this phone.');break;}
  case 'practice-use-template':{const t=templates()[Number(target.dataset.i)];if(t)practiceModal(t.text,t.name);break;}
  case 'practice-del-template':lsSet(TEMPLATES_KEY,templates().filter((_,i)=>i!==Number(target.dataset.i)));practiceModal($('#practice-text').value,$('#practice-name').value);break;
  case 'sheet-settings':sheetSettings();break;
  case 'sheet-test':sheetTest();break;
  case 'sheet-disconnect':localStorage.removeItem(SHEET_KEY);closeModal();toast('Disconnected.');if(view==='setup'||view==='results')render();break;
  case 'toggle-autosend':{const c=sheetCfg();lsSet(SHEET_KEY,{...c,auto:c.auto===false});target.setAttribute('aria-checked',String(sheetCfg().auto!==false));break;}
  case 'send-sheet':{let n=0;for(const g of session.groups)if(enqueue(g.id,{manual:true}))n++;toast(n?'Sending to the sheet…':'Nothing to send yet.');break;}
  case 'share-results':shareResults();break;
  case 'goals-sheet':goalsSheet(athlete);break;
  case 'toggle-goals':dispatch({type:'SET_PREF',key:'showGoals',value:session.prefs?.showGoals===false});target.setAttribute('aria-checked',String(session.prefs?.showGoals!==false));break;
  case 'move-pack':if(dispatch({type:'MOVE_PACK',packId:pack,dir:Number(target.dataset.dir)}))closeModal();break;
  case 'return-group':view='live';dispatch({type:'SELECT_GROUP',groupId:group});window.scrollTo({top:0,behavior:'instant'});break;
  case 'start-all':dispatch({type:'START_ALL'});break;
  case 'start-one':dispatch({type:'START_ONE',athleteId:athlete});break;
  case 'finish':dispatch({type:'FINISH',athleteId:athlete});break;
  case 'quick-finish':dispatch({type:'QUICK_FINISH'});break;
  case 'split':dispatch({type:'SPLIT',athleteId:athlete});break;
  case 'split-all':dispatch({type:'SPLIT_ALL'});break;
  case 'clear-splits':if(dispatch({type:'CLEAR_SPLITS',groupId:group,athleteId:athlete,repIndex:rep==null?undefined:Number(rep)},'Splits cleared.'))closeModal();break;
  case 'remove-capture':dispatch({type:'REMOVE_CAPTURE',groupId:group,repIndex:Number(rep),captureId:target.dataset.captureId},'Unassigned finish removed. Use Undo to restore it.');break;
  case 'start-recovery':dispatch({type:'START_RECOVERY'},'Recovery started. You can keep recording finishes.');break;
  case 'add-rest':dispatch({type:'ADD_REST',seconds:Number(target.dataset.seconds||30)},'Added 30 seconds of recovery.');break;
  case 'next-rep':nextRep();break;
  case 'add-rep':dispatch({type:'ADD_REP'},'Extra rep added.');break;
  case 'recovery-mode':dispatch({type:'SET_RECOVERY_MODE',mode:target.dataset.mode});break;
  case 'edit-time':editTime(group||session.activeGroupId,athlete,rep==null?undefined:Number(rep));break;
  case 'skip-athlete':if(dispatch({type:'SKIP_ATHLETE',groupId:group,athleteId:athlete,repIndex:rep==null?undefined:Number(rep)},'Marked as did not run.'))closeModal();break;
  case 'undo':undo();break;
  case 'save-session':saveArchive();if(view==='setup')render();break;
  case 'export':download(session);break;
  case 'export-archive':{const s=archiveRead().find(s=>s.id===target.dataset.session);if(s)download(s);break;}
  case 'open-archive':{const s=archiveRead().find(s=>s.id===target.dataset.session);if(s&&saveArchive(false)){session=clone(s);history=[];persist();view='results';render();toast('Saved session opened. Your previous session was saved first.');}break;}
  case 'view-results':view='results';render();break;
  case 'start-individual-info':toast('Tap Start beside each runner to give them their own start time.');document.querySelector('.athlete-list')?.scrollIntoView({behavior:'smooth',block:'center'});break;
  case 'edit-group':editGroup(group||session.activeGroupId);break;
  case 'copy-group':closeModal();editGroup(group,true);break;
  case 'sample-workout':$('#workout-text').value=SAMPLE_WORKOUT;updateWorkoutPreview();break;
  case 'add-group':closeModal();editGroup();break;
  case 'close-modal':closeModal();break;
  case 'toggle-sound':soundOn=!soundOn;if(soundOn){beep();audioContext?.resume();}render();toast(soundOn?'Recovery sound enabled while the page is open.':'Recovery sound off.');break;
  case 'new-session':modal('Start a fresh session?',`<p>The current session will be saved as a snapshot first. Your new session starts with the sample groups, which you can customize.</p><div class="modal-actions">${btn('Cancel','close-modal')}<button class="btn primary" id="confirm-new">Save & start new</button></div>`);$('#confirm-new').onclick=()=>{if(!saveArchive(false))return;session=createSession();history=[];alerted.clear();persist();closeModal();view='setup';render();toast('New session ready. Your previous results are saved.');};break;
}});
document.addEventListener('change',event=>{const el=event.target;if(el.matches('[data-move-pack]')){if(dispatch({type:'MOVE_ATHLETE',athleteId:el.dataset.movePack,packId:el.value||null},'Moved.'))closeModal();return;}if(el.matches('[data-capture]')&&el.value)dispatch({type:'ASSIGN_FINISH',groupId:el.dataset.group,repIndex:Number(el.dataset.rep),captureId:el.dataset.capture,athleteId:el.value},'Finish assigned.');if(el.id==='group-mode'){const free=el.value==='free';$('#planned-fields').hidden=free;$('#free-fields').hidden=!free;}});
document.addEventListener('input',event=>{if(event.target.id==='workout-text')updateWorkoutPreview();if(event.target.id==='practice-text')updatePracticePreview();if(event.target.closest?.('[data-pack-row]'))refreshAssign();});
document.addEventListener('submit',event=>{if(event.target.id==='session-form'){event.preventDefault();const name=new FormData(event.target).get('name').trim();if(!name)return;history.push(clone(session));session.name=name;persist();render();toast('Session details saved.');}});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const b=$('#modal').getBoundingClientRect();if(event.clientX<b.left||event.clientX>b.right||event.clientY<b.top||event.clientY>b.bottom)closeModal();}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateClocks();});
/* ---- Drag to reorder (grip handle) and swipe-right to delete ---- */
let drag=null,swipe=null,suppressClick=false;const DEL_W=88;
function dragUpdate(){if(!drag)return;const y=drag.y;drag.el.style.transform=`translateY(${y-drag.startY+(window.scrollY-drag.startScroll)}px)`;document.querySelectorAll('.drop-before,.drop-end').forEach(n=>n.classList.remove('drop-before','drop-end'));const secs=[...document.querySelectorAll('[data-section]')];if(!secs.length)return;let sec=secs.find(s=>{const b=s.getBoundingClientRect();return y>=b.top&&y<=b.bottom;});if(!sec)sec=secs.reduce((best,s)=>{const b=s.getBoundingClientRect(),d=Math.min(Math.abs(y-b.top),Math.abs(y-b.bottom));return !best||d<best.d?{s,d}:best;},null).s;const rows=[...sec.querySelectorAll('.athlete-swipe:not(.dragging)')],before=rows.find(rw=>{const b=rw.getBoundingClientRect();return y<b.top+b.height/2;});if(before){before.classList.add('drop-before');drag.target={pack:sec.dataset.pack,beforeId:before.dataset.athleteRow};}else{sec.classList.add('drop-end');drag.target={pack:sec.dataset.pack,afterId:rows.at(-1)?.dataset.athleteRow};}}
function dragLoop(){if(!drag)return;const top=document.querySelector('.timer-sticky')?.getBoundingClientRect().bottom||0;if(drag.y<top+46)window.scrollBy(0,-14);else if(drag.y>window.innerHeight-110)window.scrollBy(0,14);dragUpdate();drag.raf=requestAnimationFrame(dragLoop);}
function dragEnd(commit){if(!drag)return;cancelAnimationFrame(drag.raf);const d=drag;drag=null;d.el.classList.remove('dragging');d.el.style.transform='';document.querySelectorAll('.drop-before,.drop-end,.is-dragging').forEach(n=>n.classList.remove('drop-before','drop-end','is-dragging'));if(commit&&d.target&&Math.abs(d.y-d.startY)>6){const hasPacks=document.querySelector('.athlete-list')?.dataset.hasPacks==='1',action={type:'MOVE_ATHLETE',athleteId:d.id,beforeId:d.target.beforeId,afterId:d.target.afterId};if(hasPacks)action.packId=d.target.pack||null;dispatch(action);}}
document.addEventListener('pointerdown',ev=>{document.querySelectorAll('.athlete-swipe.open').forEach(w=>{if(!w.contains(ev.target))w.classList.remove('open');});const handle=ev.target.closest('[data-drag]');if(handle){ev.preventDefault();const el=handle.closest('.athlete-swipe');drag={id:handle.dataset.drag,el,startY:ev.clientY,y:ev.clientY,startScroll:window.scrollY,pointer:ev.pointerId,target:null};try{handle.setPointerCapture(ev.pointerId);}catch{}el.classList.add('dragging');el.closest('.athlete-list').classList.add('is-dragging');drag.raf=requestAnimationFrame(dragLoop);return;}const name=ev.target.closest('.athlete-name');if(name&&(ev.pointerType!=='mouse'||ev.button===0)){const wrap=name.closest('.athlete-swipe');if(wrap)swipe={wrap,row:wrap.querySelector('.athlete-row'),x:ev.clientX,y:ev.clientY,id:ev.pointerId,active:false,open:wrap.classList.contains('open'),now:0,el:name};}});
document.addEventListener('pointermove',ev=>{if(drag&&ev.pointerId===drag.pointer){drag.y=ev.clientY;return;}if(!swipe||ev.pointerId!==swipe.id)return;const dx=ev.clientX-swipe.x,dy=ev.clientY-swipe.y;if(!swipe.active){if(Math.abs(dx)>10&&Math.abs(dx)>Math.abs(dy)*1.5){swipe.active=true;swipe.row.style.transition='none';try{swipe.el.setPointerCapture(ev.pointerId);}catch{}}else if(Math.abs(dy)>10){swipe=null;return;}}if(swipe.active){swipe.now=Math.max(0,Math.min(DEL_W+14,(swipe.open?DEL_W:0)+dx));swipe.row.style.transform=`translateX(${swipe.now}px)`;}});
const gestureEnd=(ev,cancelled)=>{if(drag&&ev.pointerId===drag.pointer){dragEnd(!cancelled);return;}if(swipe&&ev.pointerId===swipe.id){if(swipe.active){swipe.row.style.transition='';swipe.row.style.transform='';swipe.wrap.classList.toggle('open',!cancelled&&swipe.now>DEL_W/2);suppressClick=true;setTimeout(()=>{suppressClick=false;},0);}swipe=null;}};
document.addEventListener('pointerup',ev=>gestureEnd(ev,false));document.addEventListener('pointercancel',ev=>gestureEnd(ev,true));
document.addEventListener('keydown',ev=>{const handle=ev.target.closest?.('[data-drag]');if(!handle||!['ArrowUp','ArrowDown'].includes(ev.key))return;ev.preventDefault();const row=handle.closest('.athlete-swipe'),sib=ev.key==='ArrowUp'?row.previousElementSibling:row.nextElementSibling;if(!sib?.dataset.athleteRow)return;const action={type:'MOVE_ATHLETE',athleteId:handle.dataset.drag};if(ev.key==='ArrowUp')action.beforeId=sib.dataset.athleteRow;else action.afterId=sib.dataset.athleteRow;dispatch(action);requestAnimationFrame(()=>document.querySelector(`[data-drag="${CSS.escape(handle.dataset.drag)}"]`)?.focus());});
/* ===== Google Sheet link, practice loader, goals, share ===== */
const SHEET_KEY='terrier-timing-sheet-v1',OUTBOX_KEY='terrier-timing-outbox-v1',TEMPLATES_KEY='terrier-timing-templates-v1',NOTIFIED_KEY='terrier-timing-notified-v1',PROMPT_KEY='terrier-timing-prompted-v1';
const lsGet=(k,d)=>{try{const v=JSON.parse(localStorage.getItem(k));return v??d;}catch{return d;}};
const lsSet=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true;}catch{return false;}};
const sheetCfg=()=>lsGet(SHEET_KEY,null);
const sheetOn=()=>{const c=sheetCfg();return !!(c&&c.url&&c.code);};
const mdToday=()=>{const d=new Date();return `${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
let sheetStatus='',flushing=false;
const sheetTimeout=ms=>{const c=new AbortController();setTimeout(()=>c.abort(),ms);return c.signal;};
async function sheetGet(params){const c=sheetCfg(),u=new URL(c.url);u.search=new URLSearchParams({tt:'1',code:c.code,...params}).toString();const res=await fetch(u,{redirect:'follow',signal:sheetTimeout(20000)});return res.json();}
async function sheetPost(body){const c=sheetCfg(),res=await fetch(c.url,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({tt:1,code:c.code,...body}),redirect:'follow',signal:sheetTimeout(30000)});return res.json();}
function parseSetupCode(text){const t=String(text||'').trim();let m=t.match(/^TT1\|(https:\/\/script\.google\.com\/[^|\s]+)\|(.+)$/);if(m)return {url:m[1],code:m[2].trim()};throw new Error('That doesn’t look like a setup code. It should start with TT1| and contain the web app link and the team code.');}

/* ---- outbox: results waiting to go to the sheet (survives weak signal and reloads) ---- */
const outbox=()=>lsGet(OUTBOX_KEY,[]);
function enqueue(groupId,{manual=false}={}){if(!sheetOn())return false;const g=getGroup(session,groupId);if(!g.records.some(hasData))return false;const key=`${session.id}:${g.id}`,notified=lsGet(NOTIFIED_KEY,[]),payload=buildSheetPayload(session,g.id);payload.notify=!!g.completed&&(manual||!notified.includes(key));const list=outbox().filter(x=>x.key!==key);list.push({key,payload,queuedAt:Date.now(),manual});lsSet(OUTBOX_KEY,list);scheduleFlush(manual?50:1500);return true;}
let flushTimer;function scheduleFlush(ms){clearTimeout(flushTimer);flushTimer=setTimeout(flushOutbox,ms);}
async function flushOutbox(){if(flushing||!sheetOn())return;let list=outbox();if(!list.length)return;if(navigator.onLine===false){sheetStatus=`${list.length} waiting for signal`;refreshSheetBits();return;}flushing=true;let sent=0,fail='',mailed=0,mailFail=false,mailErr='';
  for(const item of list){try{const res=await sheetPost(item.payload);if(!res.ok)throw new Error(res.error||'The sheet said no.');sent++;lsSet(OUTBOX_KEY,outbox().filter(x=>x.key!==item.key));if(item.payload.notify){if(res.emailed){mailed++;lsSet(NOTIFIED_KEY,[...new Set([...lsGet(NOTIFIED_KEY,[]),item.key])]);}else{mailFail=true;mailErr=res.emailError||'no reason came back, so the script may be an older version';}}}catch(err){fail=err.name==='AbortError'?'Timed out':err.message||'Failed';if(/team code/i.test(fail))break;}}
  flushing=false;const left=outbox().length;sheetStatus=left?`${left} waiting to send${fail?' · '+fail:''}`:sent?`Sent to sheet at ${new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}`:'';refreshSheetBits();if(left&&!/team code/i.test(fail))scheduleFlush(20000);if(sent&&!left)toast(mailed?'Results sent to the sheet and emailed.':mailFail?`Results sent. Email failed: ${mailErr}`:'Results sent to the Google Sheet.');}
function refreshSheetBits(){const el=document.querySelector('[data-sheet-status]');if(el)el.textContent=sheetStatus||(sheetOn()?'Connected':'Not connected');}
let lastCompleted=new Set();
function autoSend(action){if(!sheetOn()||sheetCfg().auto===false)return;if(['SELECT_GROUP','SET_PREF','MOVE_ATHLETE','MOVE_PACK','SET_PACKS','SET_GOALS','SET_MODS'].includes(action?.type))return;for(const g of session.groups)if(g.completed)enqueue(g.id);}
window.addEventListener('online',()=>scheduleFlush(500));
document.addEventListener('visibilitychange',()=>{if(!document.hidden)scheduleFlush(800);});

/* ---- connect to the sheet ---- */
function sheetSettings(){const c=sheetCfg();modal('Google Sheet',`<p>${c?'This phone is connected. Results can go to your sheet automatically.':'Paste the setup code your head coach sent. You only do this once per phone.'}</p><form id="sheet-form"><div class="field"><label for="sheet-code">Setup code</label><textarea id="sheet-code" class="form-control" rows="3" spellcheck="false" autocomplete="off" placeholder="TT1|https://script.google.com/…|team code">${c?`TT1|${e(c.url)}|${e(c.code)}`:''}</textarea><small>Starts with TT1| and has the web app link and team code.</small></div>${c?`<div class="switch-row"><div><strong>Send results automatically</strong><small>When a group finishes. You can also send from Results any time.</small></div><button type="button" class="switch" role="switch" aria-checked="${c.auto!==false}" data-action="toggle-autosend" aria-label="Send results automatically"><span></span></button></div>`:''}<div class="error-text" role="alert"></div><div class="modal-actions">${c?btn('Disconnect','sheet-disconnect',{class:'ghost danger',attrs:'type="button"'}):''}${btn('Test','sheet-test',{attrs:'type="button"'})}<button class="btn primary" type="submit">Save</button></div></form>`,()=>{const parsed=parseSetupCode($('#sheet-code').value);lsSet(SHEET_KEY,{...parsed,auto:sheetCfg()?.auto!==false});closeModal();toast('Saved. Tap Test to check the connection.');if(view==='setup'||view==='results')render();});}
async function sheetTest(){let parsed;const box=$('#modal .error-text');try{parsed=parseSetupCode($('#sheet-code').value);}catch(err){if(box)box.textContent=err.message;return;}const old=sheetCfg();lsSet(SHEET_KEY,{...parsed,auto:old?.auto!==false});if(box){box.style.color='#5b6b86';box.textContent='Checking…';}try{const res=await sheetGet({action:'ping'});if(!res.ok)throw new Error(res.error||'No answer.');if(box){box.style.color='#0b7a3b';box.textContent=`Connected. ${res.tabs.length} practice tab${res.tabs.length===1?'':'s'} found.`;}}catch(err){if(!old)localStorage.removeItem(SHEET_KEY);else lsSet(SHEET_KEY,old);if(box){box.style.color='';box.textContent=err.name==='AbortError'?'No answer from Google. Check your signal and try again.':/Failed to fetch|NetworkError|Load failed/i.test(err.message)?'Couldn’t reach the sheet. Check the link and your signal, and that the script is deployed for “Anyone”.':err.message;}}}

/* ---- practice text ---- */
const templates=()=>lsGet(TEMPLATES_KEY,[]);
function practiceSummary(text){if(!text.trim())return '<p class="form-help">Paste or fetch a practice to preview it here.</p>';try{const p=parsePractice(text),s=createSessionFromPractice(p,{now:Date.now()});return `<div class="preview-summary">${icon('check',16)} ${s.groups.length} group${s.groups.length===1?'':'s'} · ${s.groups.reduce((n,g)=>n+g.athletes.length,0)} runners</div>${s.groups.map(g=>{const mods=g.athletes.filter(a=>Object.keys(a.mods||{}).length).length,goals=g.athletes.filter(a=>Object.keys(a.goals||{}).length).length;return `<div class="pp-group"><b>${e(g.name)}</b><span class="pp-dot ${g.sheetColor}"></span><small>${getPlan(g).length} runs · ${g.athletes.length} runners${goals?` · ${goals} with goals`:''}${mods?` · ${mods} modified`:''}</small></div>`;}).join('')}`;}catch(err){return `<p class="error-text">${e(err.message)}</p>`;}}
function updatePracticePreview(){const t=$('#practice-text'),box=$('#practice-preview');if(t&&box)box.innerHTML=practiceSummary(t.value);}
function practiceModal(text='',name=''){const list=templates();modal('Load practice',`<p>Paste the practice your head coach sent, or get today’s from the sheet.</p><div class="stack">${sheetOn()?btn('Get today’s practice from sheet','practice-fetch',{icon:'download'}):btn('Connect the Google Sheet','sheet-settings',{icon:'settings'})}</div><div id="practice-tabs"></div><div class="field" style="margin-top:12px"><div class="section-top"><label for="practice-text">Practice</label><button type="button" class="small-link" data-action="practice-example">Use example</button></div><textarea id="practice-text" class="form-control workout-editor" rows="9" spellcheck="false" placeholder="Group name | blue&#10;4x400 45s rest, 6min break&#10;Johnny | 75, 6:40">${e(text)}</textarea></div><div id="practice-preview" aria-live="polite"></div><div class="field" style="margin-top:12px"><label for="practice-name">Name</label><input id="practice-name" class="form-control" maxlength="60" value="${e(name||'Practice '+mdToday())}"></div><div class="modal-actions">${btn('Save as template','practice-save-template')}${btn('Load practice','practice-load',{class:'primary'})}</div>${list.length?`<div class="reset-block"><h3>Saved templates</h3>${list.map((t,i)=>`<div class="tpl-row"><span>${e(t.name)}</span>${btn('Use','practice-use-template',{attrs:`data-i="${i}"`})}${btn('','practice-del-template',{icon:'trash',class:'ghost danger icon-btn',attrs:`data-i="${i}" aria-label="Delete template ${e(t.name)}"`})}</div>`).join('')}</div>`:''}`);updatePracticePreview();}
function loadPracticeText(text,name){let practice;try{practice=parsePractice(text);createSessionFromPractice(practice,{now:Date.now()});}catch(err){toast(err.message);return false;}
  if(session.groups.some(g=>g.records.some(hasData))&&!saveArchive(false))return false;
  session=createSessionFromPractice(practice,{name,now:Date.now(),prefs:session.prefs});history=[];alerted.clear();persist();closeModal();view='live';render();window.scrollTo({top:0,behavior:'instant'});toast('Practice loaded. Your previous session is saved.');return true;}
async function fetchPractice(tab){const box=$('#practice-tabs');if(box)box.innerHTML='<p class="form-help">Checking the sheet…</p>';try{const res=await sheetGet(tab?{action:'plan',tab}:{action:'plan',md:mdToday()});if(!res.ok)throw new Error(res.error||'No answer.');
    if(!res.found){if(box)box.innerHTML=`<p class="form-help">There’s no “Plan ${mdToday()}” tab yet.${res.tabs.length?' Pick another:':''}</p><div class="tab-pick">${res.tabs.map(t=>btn(t,'practice-fetch',{attrs:`data-tab="${e(t)}"`})).join('')}</div>`;return;}
    $('#practice-text').value=res.text;$('#practice-name').value=res.tab.replace(/^Plan\s*/,'Practice ')||$('#practice-name').value;if(box)box.innerHTML=`<p class="form-help">Loaded from “${e(res.tab)}”. Check it below, then tap Load practice.</p>`;updatePracticePreview();}
  catch(err){if(box)box.innerHTML=`<p class="error-text">${e(err.name==='AbortError'?'No answer from Google. Check your signal, or paste the practice instead.':/Failed to fetch|NetworkError|Load failed/i.test(err.message)?'Couldn’t reach the sheet. Check your signal, or paste the practice instead.':err.message)}</p>`;}}
async function todayPrompt(){if(!sheetOn()||lsGet(PROMPT_KEY,'')===new Date().toDateString())return;if(session.groups.some(g=>g.records.some(hasData)))return;lsSet(PROMPT_KEY,new Date().toDateString());
  modal('Load today’s practice?',`<p id="today-msg">Checking the sheet for “Plan ${mdToday()}”…</p><div class="modal-actions">${btn('Paste instead','practice-modal')}${btn('Not now','close-modal')}</div>`);
  try{const res=await sheetGet({action:'plan',md:mdToday()});if(!$('#today-msg')||!$('#modal').open)return;if(!res.ok)throw new Error(res.error);if(!res.found){practiceModal('', '');$('#practice-tabs').innerHTML=`<p class="form-help">There’s no “Plan ${mdToday()}” tab yet.${res.tabs.length?' Pick another:':''}</p><div class="tab-pick">${res.tabs.map(t=>btn(t,'practice-fetch',{attrs:`data-tab="${e(t)}"`})).join('')}</div>`;return;}
    practiceModal(res.text,res.tab.replace(/^Plan\s*/,'Practice '));$('#practice-tabs').innerHTML=`<p class="form-help"><b>Today’s practice is ready</b> (from “${e(res.tab)}”). Check it, then tap Load practice.</p>`;}
  catch(err){if($('#today-msg'))$('#today-msg').textContent='Couldn’t reach the sheet. You can paste the practice instead.';}}

/* ---- goals ---- */
function goalsSheet(athleteId){const g=current(),a=g.athletes.find(x=>x.id===athleteId);if(!a||g.mode!=='planned')return;const ds=plannedDistances(g);modal(`${a.name} · goals`,`<p>One goal per distance, used for every rep of that distance. Leave blank for none. Use seconds (75) or minutes:seconds (6:40).</p><form id="goals-form"><div class="mod-list">${ds.map(d=>`<div class="mod-row"><span class="mod-label"><b>${fmtDist(d)}</b></span><input class="form-control mod-dist" data-goal="${d}" inputmode="decimal" placeholder="goal" value="${a.goals?.[d]!=null?goalText(a.goals[d],'sheet'):''}" aria-label="Goal for ${fmtDist(d)}"></div>`).join('')}</div><div class="error-text" role="alert"></div><div class="modal-actions"><button class="btn primary" type="submit">Save goals</button></div></form>`,()=>{const goals={};document.querySelectorAll('#modal [data-goal]').forEach(i=>{goals[i.dataset.goal]=i.value.trim();});if(dispatch({type:'SET_GOALS',athleteId:a.id,goals},'Goals saved.'))closeModal();});}

/* ---- share ---- */
async function shareResults(){const csv='﻿'+exportCsv(session),name=`terrier-timing-${session.name.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}.csv`;try{const file=new File([csv],name,{type:'text/csv'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:session.name});return;}if(navigator.share){await navigator.share({title:session.name,text:exportCsv(session)});return;}}catch(err){if(err.name==='AbortError')return;}
  try{await navigator.clipboard.writeText(exportCsv(session));toast('Results copied. Paste them into a message or email.');}catch{download(session);}}

/* ---- goal display helpers ---- */
const hasGoals=g=>g.athletes.some(a=>Object.keys(a.goals||{}).length>0);
const goalOf=(g,a,idx)=>{if(g.mode!=='planned')return null;const p=athletePlan(g,a,idx);return p.skip?null:goalFor(g,a,idx);};
const goalClass=(g,a,idx,f)=>{const gl=goalOf(g,a,idx);return f&&gl!=null?(f.ms/1000<=gl?' beat':' missed'):'';};
const goalTagHtml=(g,a,idx)=>{const gl=goalOf(g,a,idx);return gl!=null&&session.prefs?.showGoals!==false?`<span class="goal-tag" title="Goal">${goalText(gl,'sheet')}</span>`:'';};
const sendRow=()=>`<div class="send-row">${btn(sheetOn()?'Send to sheet':'Connect sheet',sheetOn()?'send-sheet':'sheet-settings',{icon:'download'})}${btn('Share','share-results',{icon:'download'})}<span class="send-status" data-sheet-status>${e(sheetStatus||(sheetOn()?'Connected':'Not connected'))}</span></div>`;

window.addEventListener('resize',fitUpcoming);
persist();render();setInterval(updateClocks,60);setTimeout(()=>{todayPrompt();scheduleFlush(2000);},700);
